// ABLE app: state, pages, actions. Data layer lives in supabase.js.
let S={L:"id",users:[],me:null,tab:{s:"home",e:"home"},saved:[],apps:[],prof:{},as:null,prog:{},chk:[],jobs:JOBS,cands:CANDS,emps:[{n:"Andi Wijaya",bd:"",onb:50,nt:"Meja adjustable"}],co:{},set:{},q:"",fw:"",ft:"",edit:null,msgs:0,ver:[],test:null,chat:{},room:null,typing:0,focusCm:0,notes:[],streak:{n:0,last:""},theme:"",les:{},af:"all"};
try{Object.assign(S,JSON.parse(localStorage.able_sb||"{}"))}catch(e){}S.typing=0;
const L=()=>S.L,t=k=>D[k]?D[k][S.L==="id"?0:1]:k,pl=o=>o[S.L],sv=()=>{try{localStorage.able_sb=JSON.stringify(S)}catch(e){}};
const e=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const $=s=>document.querySelector(s);let toastT;
function toast(m){const x=$("#toast");x.textContent=m;clearTimeout(toastT);toastT=setTimeout(()=>x.textContent="",2800)}
const route=()=>location.hash.slice(1)||"home";const go=r=>{location.hash=r;if(route()===r)render()};
const ic=(p)=>`<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">${p}</svg>`;
const globe=ic('<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>');
const ICO={user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M21 21l-5-5"/>',book:'<path d="M4 4h7a3 3 0 013 3v13a2 2 0 00-2-2H4zM20 4h-6"/><path d="M20 4v14h-6"/>',badge:'<circle cx="12" cy="9" r="6"/><path d="M8 14l-2 7 6-3 6 3-2-7"/>',buddy:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M2 20c0-4 3-6 6-6s6 2 6 6M15 15c4 0 7 1 7 5"/>',star:'<path d="M12 3l3 6 6 1-4.500 4.500L18 21l-6-3-6 3 1.500-6.500L3 10l6-1z"/>'};
const I=k=>`<span class="m">${ic(ICO[k])}</span>`;
const TIC={home:'<path d="M3 11l9-8 9 8v10H3z"/>',prof:ICO.user,skills:ICO.star,as:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',jobs:ICO.search,apps:'<path d="M6 3h9l4 4v14H6z"/>',acad:ICO.book,buddy:ICO.buddy,co:'<path d="M4 21V5l8-2v18M12 9h8v12"/>',posts:'<path d="M12 5v14M5 12h14"/>',cands:ICO.user,badge:ICO.badge,emps:ICO.buddy};
const tI=k=>TIC[k]?ic(TIC[k]):"";
const me=()=>S.me;const isS=()=>me()&&me().role==="s",isE=()=>me()&&me().role==="e";
const skillsOf=()=>S.ver;
function match(j){const sk=skillsOf();let ov=j.sk.filter(s=>sk.includes(s)).length;let p=30+Math.round(ov/j.sk.length*40);if(S.prof.work===j.w)p+=15;if(S.prof.interest===j.cat)p+=10;if(S.prof.accr||S.prof.access)p+=3;return Math.min(98,p)}
function jobCard(j,showM){const ap=S.apps.find(a=>a.j===j.id),sd=S.saved.includes(j.id);
return `<article class="card"><h3><a href="#job-${j.id}" style="color:inherit">${e(pl(j.t))}</a></h3><div class="mut" style="display:flex;gap:.5rem;align-items:center">${lg(j.c,28)}<span>${e(j.c)} · ${e(j.loc)} · ${e(j.ty)} · ${t(j.w)}</span></div>
<p><b>${t("reqs")}:</b> ${j.sk.map(x=>`<span class="tag">${t("sk_"+x)}</span>`).join("")}</p><p><b>${t("accs")}:</b> ${e(pl(j.ac))}</p>
${showM?`<p class="m">${t("match")}: ${match(j)}%</p><button class="btn s o" data-a="save" data-v="${j.id}" aria-pressed="${sd}">${sd?t("saved")+" ✓":t("save")}</button> <button class="btn s" data-a="apply" data-v="${j.id}" ${ap?"disabled":""}>${ap?t("applied")+" ✓":t("apply")}</button>`:""}</article>`}
function header(){const r=route(),n=[["home","nav_home"],["jobs","nav_jobs"],["employers","nav_emp"],["academy","nav_acad"],["about","nav_about"],["help","help"],...(me()?[["settings","settings"]]:[])];
return `<header><div class="w bar">${me()?`<span class="logo" role="img" aria-label="ABLE">ABLE</span>`:`<a class="logo" href="#home" aria-label="ABLE">ABLE</a>`}<button class="btn s o nb" id="menu" data-a="menu" aria-expanded="false" aria-controls="nav">${t("menu")}</button><div class="sp"></div>
<nav id="nav" aria-label="Main"><ul>${n.map(([h,k])=>`<li><a href="#${h}" ${r===h?'aria-current="page"':""}>${t(k)}</a></li>`).join("")}</ul></nav>${langSel()}${themeBtn()}${me()?bell():""}
${me()?`<a class="av avs" href="#${me().role==="s"?"seeker":"employer"}" aria-label="${e(me().name)}">${okp(hp())?`<img src="${hp()}" alt="" style="width:100%;height:100%;border-radius:50%;object-fit:cover">`:e([...me().name][0]||"A").toUpperCase()}</a><a class="btn s o hb" href="#${me().role==="s"?"seeker":"employer"}">${e(me().name)}</a><button class="btn s hb" data-a="logout">${t("logout")}</button>`:`<a class="btn s o" href="#login">${t("login")}</a><a class="btn s" href="#signup">${t("signup")}</a>`}</div></header>`}
function langSel(){return `<label class="lang">${globe}<span style="position:absolute;left:-999px">${t("langl")}</span><select data-a="lang" aria-label="${t("langl")}"><option value="id" ${S.L==="id"?"selected":""}>Bahasa Indonesia</option><option value="en" ${S.L==="en"?"selected":""}>English</option></select></label>`.replace('<label class="lang">','<label class="lang" style="margin:0;font-weight:400">')}
function footer(){const so=[["Facebook","f"],["Instagram","IG"],["X (Twitter)","X"],["TikTok","TT"],["YouTube","YT"],["LinkedIn","in"]];
return `<footer><div class="w"><div>${langSel()}</div><div class="soc" aria-label="${t("social")}">${so.map(([n,l])=>`<a href="https://example.com/able-${l.toLowerCase()}" target="_blank" rel="noopener" aria-label="${n}">${l}</a>`).join("")}</div>
<ul class="fl">${["terms","gen","priv","cook"].map(k=>`<li><a href="#${k}">${t(k)}</a></li>`).join("")}<li><a href="#help">${t("help")}</a></li><li><a href="#sitemap">${t("sitemap")}</a></li></ul>
<p>${t("copy")}</p><p>${t("build")}</p></div></footer>`}
const hero=()=>`<section class="sec"><div class="w hero"><div>${me()?`<p class="ok">${t("welcome")}, ${e(me().name)}!</p>`:""}<h1>${t("h1")}</h1><p class="mut">${t("hd")}</p><p><a class="btn" href="#signup" data-r="s">${t("findjob")}</a> <a class="btn o" href="#signup" data-r="e">${t("hire")}</a></p><p class="mut">${hstats()}</p></div>
<svg class="ill" viewBox="0 0 320 240" role="img" aria-label="${t("ill")}"><rect width="320" height="240" rx="20" fill="#eaf3fb"/><rect x="30" y="150" width="260" height="12" rx="6" fill="#12284c"/><circle cx="90" cy="80" r="20" fill="#0b7a7a"/><rect x="68" y="104" width="44" height="46" rx="14" fill="#0b7a7a"/><circle cx="170" cy="85" r="18" fill="#12284c"/><rect x="150" y="106" width="40" height="40" rx="12" fill="#12284c"/><circle cx="240" cy="110" r="16" fill="#5b9bd5"/><rect x="224" y="130" width="32" height="22" rx="8" fill="#5b9bd5"/><circle cx="232" cy="175" r="14" fill="none" stroke="#12284c" stroke-width="5"/><circle cx="262" cy="175" r="14" fill="none" stroke="#12284c" stroke-width="5"/></svg></div></section>`;
function home(){const f=[["f1","search"],["f2","user"],["f3","book"],["f4","badge"],["f5","buddy"]];
return hero()+`<section class="sec alt"><div class="w"><h2>${t("about_h")}</h2><p style="max-width:70ch">${t("about_p")}</p></div></section>
${me()?"":teaser()}<section class="sec"><div class="w"><h2>${t("how_h")}</h2><div class="g">${[["s1","user"],["s2","search"],["s3","star"]].map(([k,i],n)=>`<div class="card">${I(i)}<h3>${n+1}. ${t(k)}</h3><p class="mut">${t(k+"d")}</p></div>`).join("")}</div></div></section>
<section class="sec alt"><div class="w"><h2>${t("feat_h")}</h2><div class="g">${f.map(([k,i])=>`<div class="card">${I(i)}<h3>${t(k)}</h3><p class="mut">${t(k+"d")}</p></div>`).join("")}</div></div></section>

<section class="sec"><div class="w"><h2>${t("inc_h")}</h2><p class="mut">${t("empl")}</p><div class="g">${EMPS.map(c=>`<div class="card">${I("badge")}<h3>${e(c)}</h3><span class="tag">${t("bd_h")} ✓</span></div>`).join("")}</div></div></section>
<section class="sec"><div class="w card" style="text-align:center"><h2>${t("cta_h")}</h2><a class="btn" href="#signup" data-r="s">${t("join_s")}</a> <a class="btn o" href="#signup" data-r="e">${t("join_e")}</a></div></section>`}
function jobsPage(){return `<section class="sec"><div class="w"><h1>${t("nav_jobs")}</h1>${jobFilters()}<div class="g" id="jl"></div></div></section>`}
function jobFilters(){return `<div class="g" role="search"><div><label for="q">${t("search")}</label><input id="q" type="search" value="${e(S.q)}" data-in="q"></div><div><label for="fw">${t("work")}</label><select id="fw" data-in="fw"><option value="">${t("any")}</option>${["remote","hybrid","onsite"].map(w=>`<option value="${w}" ${S.fw===w?"selected":""}>${t(w)}</option>`).join("")}</select></div><div><label for="ft">${t("type")}</label><select id="ft" data-in="ft"><option value="">${t("any")}</option>${["Full-time","Part-time","Contract"].map(w=>`<option ${S.ft===w?"selected":""}>${w}</option>`).join("")}</select></div></div>`}
function drawJobs(){const b=$("#jl");if(!b)return;const q=S.q.toLowerCase();let l=S.jobs.filter(j=>j.open&&(!S.fw||j.w===S.fw)&&(!S.ft||j.ty===S.ft)&&(!q||(pl(j.t)+j.c+j.loc+j.sk.join()).toLowerCase().includes(q)));
if(isS())l.sort((a,b)=>match(b)-match(a));b.innerHTML=l.length?l.map(j=>jobCard(j,true)).join(""):`<p class="card">${t("nojobs")}</p>`}
const cpct=c=>Math.round(((S.les[c.id]||[]).length)/c.l.length*100);
function acadCard(c){const p=cpct(c),n=(S.les[c.id]||[]).length;return `<article class="card"><span class="tag">${pl(c.lv)}</span> <span class="tag">${c.h} ${t("hours")}</span> <span class="tag">${c.l.length} ${t("lessons")}</span><h3 style="margin-top:.5rem"><a href="#course-${c.id}" style="color:inherit">${pl(c.t)}</a></h3><p class="mut">${pl(c.d)}</p>${n?`<div class="bar2" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></div><p>${p>=100?`<span class="ok">✓ ${t("complete")}</span>`:`${t("prog")}: ${p}%`}</p>`:""}<a class="btn s ${n?"":"o"}" href="#course-${c.id}">${p>=100?t("review"):n?t("cont2"):t("startc")}</a></article>`}
function acadTop(){const c=COURSES.find(x=>{const p=cpct(x);return p>0&&p<100});return c?`<div class="card" style="margin-bottom:1rem"><b>${t("cont_h")}:</b> ${pl(c.t)} (${cpct(c)}%) <a class="btn s" href="#course-${c.id}">${t("cont2")}</a></div>`:""}
function coursePage(id){const c=COURSES.find(x=>x.id===id);if(!c)return `<section class="sec"><div class="w"><a href="#academy">${t("backj")}</a></div></section>`;const dn=S.les[id]||[],p=cpct(c);
return `<section class="sec"><div class="w" style="max-width:820px"><p><a href="${isS()?"#seeker":"#academy"}">← ${t("backj")}</a></p><span class="tag">${pl(c.lv)}</span> <span class="tag">${c.h} ${t("hours")}</span><h1>${pl(c.t)}</h1><p class="mut">${pl(c.d)}</p><div class="bar2" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></div><p>${t("prog")}: ${p}%</p>
${c.l.map((l,i)=>`<details class="card hd" ${!dn.includes(i)&&(i===0||dn.includes(i-1))?"open":""}><summary>${dn.includes(i)?"✓ ":""}<b>${i+1}. ${pl(l[0])}</b></summary><p>${pl(l[1])}</p><button class="btn s ${dn.includes(i)?"o":""}" data-a="les" data-v="${id}:${i}">${dn.includes(i)?t("undo"):t("markdone")}</button></details>`).join("")}
${p>=100?`<div class="card ver" style="margin-top:1rem;text-align:center"><h2>${t("cert")}</h2><p>${e(isS()?me().name:"")}</p><p><b>${pl(c.t)}</b></p><p class="mut">${new Date().toISOString().slice(0,10)}</p><p>${t("cert_next")} <button class="btn s" data-a="astest" data-v="${c.sk}">${t("take")}</button></p></div>`:""}</div></section>`}
function acadPage(){return `<section class="sec"><div class="w"><h1>${t("nav_acad")}</h1><p class="mut">${t("acad_p")}</p><div class="g">${COURSES.map(acadCard).join("")}</div></div></section>`}
function empPage(){return `<section class="sec"><div class="w"><h1>${t("nav_emp")}</h1><p class="mut">${t("hd")}</p><div class="g">${[["f4","badge"],["f5","buddy"],["f1","search"]].map(([k,i])=>`<div class="card">${I(i)}<h3>${t(k)}</h3><p class="mut">${t(k+"d")}</p></div>`).join("")}</div><p><a class="btn" href="#signup" data-r="e">${t("join_e")}</a></p></div></section>`}
const aboutPage=()=>`<section class="sec"><div class="w"><h1>${t("about_h")}</h1><p style="max-width:70ch">${t("about_p")}</p><p class="m">${t("tag")}</p></div></section>`;
const legal=k=>`<section class="sec"><div class="w"><h1>${t(k)}</h1><ul>${PAGES[k].map(l=>`<li>${l[S.L==="id"?0:1]}</li>`).join("")}</ul></div></section>`;
const sitemap=()=>`<section class="sec"><div class="w"><h1>${t("sitemap")}</h1><ul>${[["home","nav_home"],["jobs","nav_jobs"],["employers","nav_emp"],["academy","nav_acad"],["about","nav_about"],["login","login"],["signup","signup"],["terms","terms"],["gen","gen"],["priv","priv"],["cook","cook"],["help","help"]].map(([h,k])=>`<li><a href="#${h==="gen"?"general":h}">${t(k)}</a></li>`).join("")}</ul></div></section>`;
let regRole="s";
const dd=(n,k,ks)=>`<label for="${n}">${t(k)}</label><select id="${n}" name="${n}"><option value="">${t("choose")}</option>${ks.map(x=>`<option value="${x}">${t(x)}</option>`).join("")}</select>`;
const fld=(n,k,ty="text",req=1,v="")=>`<label for="${n}">${t(k)}${req?" *":""}</label><input id="${n}" name="${n}" type="${ty}" value="${e(v)}" ${req?"required":""} autocomplete="${n==="email"?"email":n==="password"?"current-password":"off"}">`;
function signup(){const s=regRole==="s";return `<section class="sec"><div class="w" style="max-width:560px"><h1>${t(s?"reg_s":"reg_e")}</h1><div class="tabs" role="tablist">${["s","e"].map(r=>`<button role="tab" aria-selected="${regRole===r}" data-a="role" data-v="${r}">${t("as_"+(r==="s"?"s":"e"))}</button>`).join("")}</div>
<form class="card" data-f="signup" novalidate>${sb?"":`<div class="err">${t("demo_mode")}</div>`}<div id="errs" role="alert"></div>${s?fld("name","name")+fld("email","email","email")+fld("password","pass","password")+fld("phone","phone","tel")+dd("dis","dis",["dis_none","dis_phys","dis_vis","dis_hear","dis_int","dis_ment","dis_neuro","dis_other"])+dd("accr","accr",["acc_none","acc_wheel","acc_screen","acc_sign","acc_flex","acc_quiet","acc_remote","acc_other"]):fld("name","cname")+fld("email","cemail","email")+fld("ind","ind")+`<label for="cdesc">${t("cdesc")} *</label><textarea id="cdesc" name="cdesc" rows="2" required></textarea>`+fld("web","web","url")+fld("cp","cp")+fld("password","pass","password")}<p><button class="btn">${t("signup")}</button></p></form></div></section>`}
function login(){return `<section class="sec"><div class="w" style="max-width:480px"><h1>${t("login_h")}</h1><form class="card" data-f="login" novalidate>${sb?"":`<div class="err">${t("demo_mode")}</div>`}<div id="errs" role="alert"></div>${fld("email","email","email")}${fld("password","pass","password")}<p><button class="btn">${t("login")}</button></p><p class="mut">${t("demo")}</p><p><a href="#forgot">${t("forgot")}</a></p></form></div></section>`}
const skillsTab=()=>!sb?`<p class="card">${t("need_sb")}</p>`:S.test?testForm(S.test):`<div class="g">${Object.keys(SK).map(k=>`<div class="card">${I("star")}<h3>${t("sk_"+k)}</h3>${S.ver.includes(k)?`<p class="ok">✓ ${t("verified")}</p>`:`<p class="mut">${t("unver")}</p>`}<button class="btn s ${S.ver.includes(k)?"o":""}" data-a="test" data-v="${k}">${S.ver.includes(k)?t("retake"):t("take")}</button></div>`).join("")}</div>`;
function testForm(te){const i=S.L==="id"?0:1,T=te.qs?te.qs.map(x=>[x.q]):[];if(te.res)return `<div class="card"><h2>${t("sk_"+te.skill)}</h2><p class="${te.res.passed?"ok":"err"}">${te.res.passed?"✓ "+t("tpass"):t("tfail")} (${te.res.score}/${te.res.total})</p>${te.res.passed?"":`<button class="btn s" data-a="test" data-v="${te.skill}">${t("retake")}</button> `}<button class="btn s o" data-a="tclose">${t("back")}</button></div>`;
return `<form class="card" data-f="test" autocomplete="off"><h2>${t("sk_"+te.skill)}</h2><p class="mut">${t("test_i")}</p>${T.map((q,n)=>`<label for="q${n}">${n+1}. ${e(q[0][i])}</label><input id="q${n}" name="q${n}" required placeholder="${t("answer")}">`).join("")}<p><button class="btn">${t("submit_test")}</button> <button type="button" class="btn o" data-a="tclose">${t("back")}</button></p></form>`}
function homeS(){const by={};S.jobs.filter(j=>j.open).forEach(j=>(by[j.c]=by[j.c]||[]).push(j));const rec=S.jobs.filter(j=>j.open&&!S.apps.some(a=>a.j===j.id)).sort((a,b)=>match(b)-match(a)).slice(0,3);
return `${learnRow()}<div class="g" style="margin-top:1rem">${[["stat_ver",S.ver.length+"/4"],["stat_apps",S.apps.length],["stat_saved",S.saved.length]].map(([k,v])=>`<div class="card"><div class="m" style="font-size:1.8rem">${v}</div>${t(k)}</div>`).join("")}</div>${S.ver.length?"":`<p class="card" style="margin-top:1rem">${t("noskv")}</p>`}
<h2 style="margin-top:1.5rem">${t("hiring_h")}</h2><div class="g">${Object.keys(by).map(c=>`<div class="card"><div class="rw">${lg(c,48)}<h3 style="margin:0">${e(c)}</h3></div><span class="tag">● ${t("hiring")}</span> <span class="tag">${by[c].length} ${t("openpos")}</span><p class="mut">${by[c].map(j=>e(pl(j.t))).join(", ")}</p><button class="btn s o" data-a="viewco" data-v="${e(c)}">${t("viewjobs")}</button></div>`).join("")}</div>
<h2 style="margin-top:1.5rem">${t("rec")}</h2><div class="g">${rec.map(j=>jobCard(j,true)).join("")}</div>`}
function homeE(){const m=mine(),ids=m.map(j=>j.id),ap=S.cands.filter(c=>ids.includes(c.jid));
const best=p=>{let b=-1,bj=null;m.filter(j=>j.open).forEach(j=>{const x=cMatch(j,p);if(x>b){b=x;bj=j}});return bj?`${t("match")} ${b}% · ${e(pl(bj.t))}`:""};
return `<div class="g">${[["stat_jobs",m.filter(j=>j.open).length],["stat_app",ap.length],["stat_tal",ALLT().length]].map(([k,v])=>`<div class="card"><div class="m" style="font-size:1.8rem">${v}</div>${t(k)}</div>`).join("")}</div><p><button class="btn" data-a="tab" data-v="posts">${t("newjob")}</button></p>
<h2>${t("applicants_h")}</h2>${m.length?`<div class="card sc"><table><tr><th>${t("jt")}</th><th>${t("reqsk")}</th><th>${t("applicants")}</th></tr>${m.map(j=>`<tr><td>${e(pl(j.t))}<br><span class="tag">${j.open?t("open"):t("closed")}</span></td><td>${j.sk.map(x=>`<span class="tag">${t("sk_"+x)}</span>`).join("")}</td><td><b>${ap.filter(c=>c.jid===j.id).length}</b></td></tr>`).join("")}</table></div>`:`<p class="card">${t("noposts")}</p>`}
<h2 style="margin-top:1.5rem">${t("talent_h")}</h2><div class="g">${ALLT().slice().sort((a,b)=>b.v.length-a.v.length).map(p=>`<div class="card"><div class="rw">${av("",p.n,44)}<h3 style="margin:0">${e(p.n)}</h3></div><p class="mut">${e(p.ed)} · ${e(p.loc)}</p><p>${p.v.map(x=>`<span class="tag">✓ ${t("sk_"+x)}</span>`).join("")}</p><p class="m">${best(p)}</p></div>`).join("")}</div>`}
function candsE(){return mine().map(j=>{const l=S.cands.filter(c=>c.jid===j.id).sort((a,b)=>cMatch(j,b)-cMatch(j,a));return `<h2 style="margin-top:1.5rem">${e(pl(j.t))}: ${l.length} ${t("applicants")}</h2><p class="mut">${t("reqsk")}: ${j.sk.map(x=>`<span class="tag">${t("sk_"+x)}</span>`).join("")}</p>${l.length?`<div class="g">${l.map(k=>candCard(j,k)).join("")}</div>`:`<p class="card">${t("noappl")}</p>`}`}).join("")||`<p class="card">${t("noposts")}</p>`}
